def _worker_thread_transfer(self):
        # type: (SyncCopy) -> None
        """Worker thread download
        :param SyncCopy self: this
        """
        while self.running:
            try:
                self.transfer_queue.get(block=True, timeout=1)
            except queue.Empty:
                continue
            except Exception as e:
                self.logger.error("Exception in transfer thread: %s", e)
                self.running = False
                break

            self.logger.debug("Transferring file %s", self.transfer_queue.queue[0])
            try:
                self.transfer_queue.queue[0].transfer(self.dest_path)
            except Exception as e:
                self.logger.error("Exception in transfer thread: %s", e)
                self.running = False
                break
            finally:
                self.transfer_queue.task_done()

